package sun.java2d.marlin;

/**
 * Faster Math ceil / floor routines derived from StrictMath
 */
public final class FloatMath implements MarlinConst {

    // overflow / NaN handling enabled:
    static final boolean CHECK_OVERFLOW = true;
    static final boolean CHECK_NAN = true;
    // Copied from sun.misc.FloatConsts:
    public static final int FLOAT_SIGNIFICAND_WIDTH = 24;   // sun.misc.FloatConsts.SIGNIFICAND_WIDTH
    public static final int FLOAT_EXP_BIAS = 127;           // sun.misc.FloatConsts.EXP_BIAS
    public static final int FLOAT_EXP_BIT_MASK = 2139095040;// sun.misc.FloatConsts.EXP_BIT_MASK
    public static final int FLOAT_SIGNIF_BIT_MASK = 8388607;// sun.misc.FloatConsts.SIGNIF_BIT_MASK

    private FloatMath() {
        // utility class
    }

    // faster inlined min/max functions in the branch prediction is high
    static int max(final int a, final int b) {
        return (a >= b) ? a : b;
    }

    static int min(final int a, final int b) {
        return (a <= b) ? a : b;
    }

    /**
     * Returns the smallest (closest to negative infinity) {@code float} value
     * that is greater than or equal to the argument and is equal to a
     * mathematical integer. Special cases:
     * <ul><li>If the argument value is already equal to a mathematical integer,
     * then the result is the same as the argument.  <li>If the argument is NaN
     * or an infinity or positive zero or negative zero, then the result is the
     * same as the argument.  <li>If the argument value is less than zero but
     * greater than -1.0, then the result is negative zero.</ul> Note that the
     * value of {@code StrictMath.ceil(x)} is exactly the value of
     * {@code -StrictMath.floor(-x)}.
     *
     * @param a a value.
     * @return the smallest

import {ReferenceProvider, TextDocument, Position, Location, ReferenceContext} from 'vscode';
import nrepl_client = require('nrepl-client');
import edn = require('jsedn');
import {EditorUtils} from './editorUtils';

export class ClojureReferenceProvider implements ReferenceProvider {

  private referencesCode(document: TextDocument, position: Position): [string, string] {
    let fileContents = document.getText();
    var regex = /\(ns\s+?(.*?)(\s|\))/;
    var ns = regex.exec(fileContents.toString())[1];
    let prefixRange = document.getWordRangeAtPosition(position);
    var prefix = document.getText(prefixRange);
    let offset = document.offsetAt(position) - 1;
    var src = fileContents.substring(0, offset) + "__prefix__" + fileContents.substring(offset + prefix.length);
    src = EditorUtils.escapeClojureCodeInString(src);

    let rval =
    `(do (require '[clojure.tools.namespace.dir :as dir])
     (require '[clojure.tools.namespace.track :as track])
     (let [])
     (defn make-proxy
      [reader count-atom]
      (proxy [java.io.PushbackReader clojure.lang.IDeref] [reader]
       (deref [] @count-atom)
       (read [] (do (swap! count-atom inc) (proxy-super read)))
       (unread [c] (do (swap! count-atom dec) (proxy-super unread c)))))

     (defn find-high-level-form
      [src position]
      (let[rdr (make-proxy (java.io.StringReader. src) (atom 0))]
       (loop [form (binding [*read-eval* false] (read rdr)) pos @rdr]
        (if (> pos position)
         form
         (recur (binding [*read-eval* false] (read rdr)) @rdr)))))

     (let [src ${src}
           pos ${offset}
           ctx (str (find-high-level-form src pos))]
      (let [completions (compliment.core/completions
                         \"${prefix}\"
                         {:tag-candidates true
                          :ns '${ns}
                          :ctx ctx})]
        (->> completions
             (take 3050)
             (mapv #(assoc % :docs (compliment.core/documentation
                                    (:candidate %) '${ns})))))))`;
    return [rval, prefix];
  }

  public provideReferences(document: TextDocument, position: Position, context: ReferenceContext): Thenable<Location[]> {
    let self = this;
    return new Promise<Location[]>((resolve, reject) => {
      let wordRange = document.getWordRangeAtPosition(position);
      let symbol = document.getText(wordRange);

    });
  }
}
